{
  "book_code": "2ES",
  "verses": [
    {
      "chapter": 11,
      "text_ar": "اسمعوا أنتم الذين حكمتم على الأرض طوال هذا الوقت! أعلن هذا لكم قبل أن تزولوا،",
      "verse": 16
    },
    {
      "chapter": 11,
      "text_ar": "لن يحكم أحد بعدكم طدكم مثلكم، ولا حتى نصف تلك المدة.",
      "verse": 17
    },
    {
      "chapter": 11,
      "text_ar": "ثم قام الثالث وحكم مثل الذين قبله، وزال هو أيضاً.",
      "verse": 18
    },
    {
      "chapter": 11,
      "text_ar": "وهكذا جرى الأمر مع كل الأجنحة واحداً تلو الآخر، إذ حكم كل منها ثم زال.",
      "verse": 19
    },
    {
      "chapter": 11,
      "text_ar": "ورأيت، وهأنذا في مسيرة الوقت الأجنحة التي تلتها أُقيمت على اليمين لكي تحكم هي أيضاً. وحكم البعض منها، ولكنها زالت بعد قليل.",
      "verse": 20
    }
  ]
}
